package org.apache.commons.math.optimization.direct;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.optimization.FunctionEvaluationException;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.RealConvergenceChecker;
import org.apache.commons.math.optimization.RealPointValuePair;
import org.apache.commons.math3.optim.RealPointValuePair;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunction;
import org.apache.commons.math3.optim.nonlinear.scalar.noderiv.NelderMeadSimplex;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for MultiDirectional.iterateSimplex.
 * Since iterateSimplex is protected, we use a spy or a subclass to test it.
 */
public class MultiDirectional_iterateSimplex_TriageGen1Test {

    private MultiDirectionalTestable multiDirectional;
    private Comparator<RealPointValuePair> comparator;
    private RealPointValuePair bestPoint;
    private RealPointValuePair reflectedPoint;
    private RealPointValuePair expandedPoint;
    private RealPointValuePair contractedPoint;

    // Subclass to expose protected method and allow mocking of protected methods
    private static class MultiDirectionalTestable extends MultiDirectional {
        public MultiDirectionalTestable(double khi, double gamma) {
            super(khi, gamma);
        }

        @Override
        public void iterateSimplex(Comparator<RealPointValuePair> comparator) 
                throws FunctionEvaluationException, OptimizationException, IllegalArgumentException {
            super.iterateSimplex(comparator);
        }

        // Expose simplex for testing setup
        public void setSimplex(RealPointValuePair[] simplex) {
            try {
                java.lang.reflect.Field field = MultiDirectional.class.getDeclaredField("simplex");
                field.setAccessible(true);
                field.set(this, simplex);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        // Mockable methods
        protected RealPointValuePair[] evaluateNewSimplex(RealPointValuePair[] original, double scale, Comparator<RealPointValuePair> comp) 
                throws FunctionEvaluationException {
            return null; // Overridden by spy
        }
    }

    @Before
    public void setUp() {
        multiDirectional = spy(new MultiDirectionalTestable(2.0, 0.5));
        comparator = mock(Comparator.class);

        bestPoint = mock(RealPointValuePair.class);
        reflectedPoint = mock(RealPointValuePair.class);
        expandedPoint = mock(RealPointValuePair.class);
        contractedPoint = mock(RealPointValuePair.class);

        RealPointValuePair[] simplex = new RealPointValuePair[]{bestPoint, mock(RealPointValuePair.class)};
        multiDirectional.setSimplex(simplex);
    }

    @Test
    public void testIterateSimplex_ReflectedIsBetter_ExpandedIsBetter() throws Exception {
        // Scenario: reflected < best AND reflected <= expanded
        // Result: accept reflected, return.

        doReturn(new RealPointValuePair[]{bestPoint, reflectedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(1.0), any());
        doReturn(new RealPointValuePair[]{bestPoint, expandedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(2.0), any()); // khi = 2.0

        when(comparator.compare(reflectedPoint, bestPoint)).thenReturn(-1);
        when(comparator.compare(reflectedPoint, expandedPoint)).thenReturn(-1);

        multiDirectional.iterateSimplex(comparator);

        verify(multiDirectional, times(1)).evaluateNewSimplex(any(), eq(1.0), any());
        verify(multiDirectional, times(1)).evaluateNewSimplex(any(), eq(2.0), any());
    }

    @Test
    public void testIterateSimplex_ReflectedIsBetter_ExpandedIsWorse() throws Exception {
        // Scenario: reflected < best AND reflected > expanded
        // Result: accept reflected (logic in code says if reflected <= expanded, accept reflected, 
        // but if reflected > expanded, it doesn't assign reflectedSimplex to simplex, 
        // however the loop structure is tricky. In provided code: 
        // if (compare(reflected, expanded) <= 0) { simplex = reflectedSimplex; } return;
        // If reflected > expanded, it falls through and returns without updating simplex.

        doReturn(new RealPointValuePair[]{bestPoint, reflectedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(1.0), any());
        doReturn(new RealPointValuePair[]{bestPoint, expandedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(2.0), any());

        when(comparator.compare(reflectedPoint, bestPoint)).thenReturn(-1);
        when(comparator.compare(reflectedPoint, expandedPoint)).thenReturn(1);

        multiDirectional.iterateSimplex(comparator);

        verify(multiDirectional, times(1)).evaluateNewSimplex(any(), eq(1.0), any());
        verify(multiDirectional, times(1)).evaluateNewSimplex(any(), eq(2.0), any());
    }

    @Test
    public void testIterateSimplex_ReflectedNotBetter_ContractedIsBetter() throws Exception {
        // Scenario: reflected >= best AND contracted < best
        // Result: accept contracted (logic is empty in provided snippet, but returns)

        doReturn(new RealPointValuePair[]{bestPoint, reflectedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(1.0), any());
        doReturn(new RealPointValuePair[]{bestPoint, contractedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(0.5), any()); // gamma = 0.5

        when(comparator.compare(reflectedPoint, bestPoint)).thenReturn(1);
        when(comparator.compare(contractedPoint, bestPoint)).thenReturn(-1);

        multiDirectional.iterateSimplex(comparator);

        verify(multiDirectional, times(1)).evaluateNewSimplex(any(), eq(1.0), any());
        verify(multiDirectional, times(1)).evaluateNewSimplex(any(), eq(0.5), any());
    }

    @Test
    public void testIterateSimplex_ReflectedNotBetter_ContractedNotBetter_LoopAgain() throws Exception {
        // Scenario: reflected >= best AND contracted >= best
        // The loop continues. We need to trigger a second iteration where it eventually returns.
        // To avoid infinite loop in test, we make the second iteration return via reflected < best.

        // First iteration: reflected >= best, contracted >= best
        doReturn(new RealPointValuePair[]{bestPoint, reflectedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(1.0), any());
        doReturn(new RealPointValuePair[]{bestPoint, contractedPoint}).when(multiDirectional)
                .evaluateNewSimplex(any(), eq(0.5), any());

        when(comparator.compare(reflectedPoint, bestPoint)).thenReturn(1); // reflected not better
        when(comparator.compare(contractedPoint, bestPoint)).thenReturn(1); // contracted not better

        // Second iteration: reflected < best
        // We use doReturn with different values for consecutive calls
        doReturn(new RealPointValuePair[]{bestPoint, reflectedPoint})
                .doReturn(new RealPointValuePair[]{bestPoint, reflectedPoint})
                .when(multiDirectional).evaluateNewSimplex(any(), eq(1.0), any());

        // We need to control the comparator to return -1 on the second call
        when(comparator.compare(any(), any()))
                .thenReturn(1)  // Iteration 1: reflected vs best
                .thenReturn(1)  // Iteration 1: contracted vs best
                .thenReturn(-1); // Iteration 2: reflected vs best

        multiDirectional.iterateSimplex(comparator);

        verify(multiDirectional, times(2)).evaluateNewSimplex(any(), eq(1.0), any());
    }
}
